(2605505, 361239, 53316, '<td valign="top">I love the feel of this except it is just a tad too paintbrushed-feeling for me.  But overall I think it is great.</td>', 'I love the feel of this except it is just a tad too paintbrushed-feeling for me.  But overall I think it is great.', '2006-07-10 02:05:15.000000', NULL, 1),
(2605516, 361086, 33672, '<td valign="top">My favorite military plane. Nice capture, very sharp.</td>', 'My favorite military plane. Nice capture, very sharp.', '2006-07-10 02:09:32.000000', NULL, 1),
(2605525, 360897, 11923, '<td valign="top">Nice luminance in this image.  Lighting is just right.  Spot on for the challenge.  Focus looks good though a tad soft in a few areas and a bit of artifacting but that could be due to compression.  Well done.  6</td>', 'Nice luminance in this image.  Lighting is just right.  Spot on for the challenge.  Focus looks good though a tad soft in a few areas and a bit of artifacting but that could be due to compression.  Well done.  6', '2006-07-10 02:11:50.000000', NULL, 1),
(2605527, 359822, 52981, '<td valign="top">10 eyes, 10 points from me, very nice peace.</td>', '10 eyes, 10 points from me, very nice peace.', '2006-07-10 02:12:19.000000', NULL, 1),
(2605534, 361037, 11923, '<td valign="top">Nice crisp image.  The title helps fit it to the challenge as he doesn''t scream ten years old to me, but no matter.  Nice use of natural light and some may find the bubbles distracting but I really like the effect they give.  Almost light fairy lights.  5.</td>', 'Nice crisp image.  The title helps fit it to the challenge as he doesn''t scream ten years old to me, but no matter.  Nice use of natural light and some may find the bubbles distracting but I really like the effect they give.  Almost light fairy lights.  5.', '2006-07-10 02:14:23.000000', NULL, 1),
(2605536, 360946, 11923, '<td valign="top">Cute.  Nice composition, humorous and good lighting, prop use and sharpness. 7.</td>', 'Cute.  Nice composition, humorous and good lighting, prop use and sharpness. 7.', '2006-07-10 02:15:26.000000', NULL, 1),
(2605542, 360398, 16241, '<td valign="top">adorable!</td>', 'adorable!', '2006-07-10 02:16:56.000000', NULL, 1),
