INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2607585, 360281, 59130, '<td valign="top">Lovely shot, though I''m not sure about the blurry corners - makes it look a bit tacky for my taste and I think the image would have been stronger without them.  I like it though, and the toes are beautifully in focus. 7</td>', 'Lovely shot, though I''m not sure about the blurry corners - makes it look a bit tacky for my taste and I think the image would have been stronger without them.  I like it though, and the toes are beautifully in focus. 7', '2006-07-10 15:36:38.000000', NULL, 1),
(2607586, 361232, 42100, '<td valign="top">I''m not sure why I liked this one, feet are not something I''m particularly fond of seeing. LOL.  I guess good technical execution always speaks for itself.</td>', 'I''m not sure why I liked this one, feet are not something I''m particularly fond of seeing. LOL.  I guess good technical execution always speaks for itself.', '2006-07-10 15:36:38.000000', NULL, 1),
