(2609790, 358407, 57358, '<td valign="top">wish the background were whiter, but I like your composition, also red dice and having the focus on the dice while everything else is a bit softer really helps to bring the attention to them</td>', 'wish the background were whiter, but I like your composition, also red dice and having the focus on the dice while everything else is a bit softer really helps to bring the attention to them', '2006-07-11 02:40:45.000000', NULL, 1),
(2609797, 358400, 57358, '<td valign="top">wow, nice grunge effect, I like your composition as well, what a neat idea for the challenge, I like the burning around the edges to bring out the hands, and the emotion really stands out with the old hand and the young one, 8</td>', 'wow, nice grunge effect, I like your composition as well, what a neat idea for the challenge, I like the burning around the edges to bring out the hands, and the emotion really stands out with the old hand and the young one, 8', '2006-07-11 02:42:45.000000', NULL, 1),
