(2625618, 361055, 43400, '<td valign="top">i like the concept and composition, but not sure of the coloring--looks too "applied". good potential w/other angles.</td>', 'i like the concept and composition, but not sure of the coloring--looks too "applied". good potential w/other angles.', '2006-07-15 22:17:48.000000', NULL, 1),
(2625623, 359957, 41200, '<td valign="top">Easily one of the stongest images in the challenge. The selective saturation works well. Bumping to a 10.</td>', 'Easily one of the stongest images in the challenge. The selective saturation works well. Bumping to a 10.', '2006-07-15 22:19:17.000000', NULL, 1),
(2625664, 360437, 31403, '<td valign="top">Great creative - love this idea<br/> <br/>Would love to see more contrast - whiter whites - blacker blacks - I think this would push your reds too - I would love to see those more saturated.<br/> <br/>Maybe from a compositional standpoint, shoot so the lines of the board are at harsher angles to the edges of your frame and I think you''ll find a stonger composition.<br/> <br/>Great idea though - nice work.</td>', 'Great creative - love this idea Would love to see more contrast - whiter whites - blacker blacks - I think this would push your reds too - I would love to see those more saturated. Maybe from a compositional standpoint, shoot so the lines of the board are at harsher angles to the edges of your frame and I think you''ll find a stonger composition. Great idea though - nice work.', '2006-07-15 22:42:03.000000', NULL, 1),
