INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2628261, 359854, 41337, '<td valign="top">Congrats. Did you have to crop out any or was this the exact number that were out there.</td>', 'Congrats. Did you have to crop out any or was this the exact number that were out there.', '2006-07-17 01:18:15.000000', NULL, 0),
(2628262, 359829, 19952, '<td valign="top">I like this shot a lot -- very creative take on this challenge. In response to your note about getting the camera to focus on the distance, you could just pre-focus on the target you want, then switch your lens to manual focus so you don''t have to worry about it any more.</td>', 'I like this shot a lot -- very creative take on this challenge. In response to your note about getting the camera to focus on the distance, you could just pre-focus on the target you want, then switch your lens to manual focus so you don''t have to worry about it any more.', '2006-07-17 01:18:16.000000', NULL, 0),
