INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2757771, 360957, 39184, '<td valign="top">Good idea and creative.  I didn''t see the number 10 at first though, maybe because of the spacing between some of the bears.  The subjects seem a little soft on the focus and I''m trying to figure out why.  I might be wrong, but my guess is that you hand held this shot.  If you did, then that is probably why it appears soft.  It is difficult to get a clean, sharp shot with a shutter speed of 1/8s without a tripod.  Was it hand held or am I way off base?</td>', 'Good idea and creative.  I didn''t see the number 10 at first though, maybe because of the spacing between some of the bears.  The subjects seem a little soft on the focus and I''m trying to figure out why.  I might be wrong, but my guess is that you hand held this shot.  If you did, then that is probably why it appears soft.  It is difficult to get a clean, sharp shot with a shutter speed of 1/8s without a tripod.  Was it hand held or am I way off base?', '2006-08-24 19:49:01.000000', NULL, 0),
